INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(2401, 'Exodus 33:2', 'Exodus', 33, 2, '&nbsp;زۀ به ستاسو نه مخکښې يوه فرښته ولېږم او زۀ به کنعانيان، اموريان، حِتيان، فرزيان، حِويان او يبوسيان وشړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2402, 'Exodus 33:3', 'Exodus', 33, 3, '&nbsp;تاسو هغه زرخېزې زمکې له ورروان شئ. خو زۀ به په خپله تاسو سره نۀ ځم، ځکه چې تاسو ضدى خلق يئ او کېدے شى چې زۀ تاسو په لاره کښې تباه کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2403, 'Exodus 33:4', 'Exodus', 33, 4, '&nbsp;چې کله خلقو دا واورېدل، نو هغوئ په ژړا شروع وکړه او هغوئ نور کالى اچول بند کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2404, 'Exodus 33:5', 'Exodus', 33, 5, '&nbsp;ځکه چې مالِک خُدائ موسىٰ ته فرمائيلى وُو چې هغوئ ته ووايه چې، ”تاسو ضدى خلق يئ. کۀ زۀ د لږ وخت دپاره هم ستاسو سره تلے وے، نو ما به تاسو تباه کړى وئ. اوس خپل کالى لرې کړئ، نو زۀ به فېصله وکړم چې ستاسو سره څۀ چل وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2405, 'Exodus 33:6', 'Exodus', 33, 6, '&nbsp;چې کله اِسرائيليان د سينا غرۀ نه لاړل، نو هغوئ نور کالى اچول بس کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2406, 'Exodus 33:7', 'Exodus', 33, 7, '&nbsp;چې کله به هم بنى اِسرائيلو خېمې ودرولې، نو موسىٰ به مقدسه خېمه وړله او د خېمو د ځائ نه لږه لرې به يې ودروله. او هغې ته به يې ”د مالِک خُدائ د حضور خېمه“ نوم اخستلو او چې چا به هم د مالِک خُدائ رضا معلومول غوښتل نو هغه به ورتللو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2407, 'Exodus 33:8', 'Exodus', 33, 8, '&nbsp;چې کله به هم موسىٰ هلته تللو، نو خلق به پاڅېدل او د خپلو خېمو په خولۀ کښې ودرېدل او موسىٰ ته به يې تر هغې پورې کتل چې ورننه به وتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2408, 'Exodus 33:9', 'Exodus', 33, 9, '&nbsp;څنګه چې به موسىٰ دننه تلو نو د وريځې ستن به لاندې راتله او د خېمې د دروازې په خولۀ کښې به ودرېدله او مالِک خُدائ به د وريځې نه د موسىٰ سره خبرې کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2409, 'Exodus 33:10', 'Exodus', 33, 10, '&nbsp;چې څنګه به خلقو د خېمې د دروازې په خولۀ کښې د وريځې ستن وليدله، نو هر يو کس به پاڅېدلو او د خپلې خپلې خېمې د دروازې په خولۀ کښې به يې سجده کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2410, 'Exodus 33:11', 'Exodus', 33, 11, '&nbsp;مالِک خُدائ به د موسىٰ سره مخامخ خبرې کولې، لکه چې يو کس يې د خپل ملګرى سره کوى. بيا به موسىٰ خېمو ته واپس راتلو. خو هغه زلمے، د نون زوئ، يشوَع چې د هغۀ مددګار وو، هغه به په خېمه کښې ايسارېدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2411, 'Exodus 33:12', 'Exodus', 33, 12, '&nbsp;موسىٰ مالِک خُدائ ته وفرمائيل، ”ګوره، تا ما ته فرمائيلى دى چې دا خلق به هغه زمکې ته بوځم، خو تا ما ته دا ونۀ فرمائيل چې زما سره به تۀ څوک لېږې. تا ما ته فرمائيلى دى چې تا زۀ ښۀ پېژنم او ستا نه رضا يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2412, 'Exodus 33:13', 'Exodus', 33, 13, '&nbsp;اوس زۀ تا ته سوال کوم، تۀ ما ته خپلې ارادې وښايه چې زۀ ستا خِدمت وکړم او تا رضا کړم. دا هم ياد ساته چې تا دا قوم خپل خلق ګڼلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2413, 'Exodus 33:14', 'Exodus', 33, 14, '&nbsp;مالِک خُدائ وفرمائيل، ”زۀ به په خپله تا سره ځم او زۀ به تا له آرام درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2414, 'Exodus 33:15', 'Exodus', 33, 15, '&nbsp;موسىٰ ورته وفرمائيل، ”کۀ تۀ مونږ سره نۀ ځې، نو مونږ د دې ځائ نه مۀ بوځه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2415, 'Exodus 33:16', 'Exodus', 33, 16, '&nbsp;چې تۀ مونږ سره نۀ ځې نو چا ته به څنګه پته ولګى چې تۀ د خپلو خلقو او زما نه رضا يې؟ تۀ چې مونږ سره يې، نو چې د زمکې په مخ څومره خلق دى د هغوئ نه به مونږ بل شان شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2416, 'Exodus 33:17', 'Exodus', 33, 17, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”زۀ به هم هغه شان وکړم لکه چې تا څنګه وئيلى دى، ځکه چې تا زۀ ښۀ پېژنم او زۀ ستا نه رضا يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2417, 'Exodus 33:18', 'Exodus', 33, 18, '&nbsp;بيا موسىٰ وفرمائيل، ”ما له اجازت راکړه چې زۀ ستا د حضور جلال ووينم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2418, 'Exodus 33:19', 'Exodus', 33, 19, '&nbsp;مالِک خُدائ وفرمائيل، ”زما شان او شوکت به ستا په مخکښې تېر شى او ستا په مخکښې به زۀ خپل مقدس نوم واخلم کوم چې مالِک خُدائ دے. زۀ مالِک خُدائ يم او څوک چې زۀ غوره کړم زۀ هغوئ ته خپل رحم او ترس ښايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2419, 'Exodus 33:20', 'Exodus', 33, 20, '&nbsp;تۀ به زما ديدار ونۀ کړې، ځکه چې دا نۀ شى کېدے چې څوک ما وګورى او ژوندى پاتې شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2420, 'Exodus 33:21', 'Exodus', 33, 21, '&nbsp;خو ګوره، زما سره نزدې يو ځائ دے، تۀ هلته په يو ګټ باندې ودرېدے شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2421, 'Exodus 33:22', 'Exodus', 33, 22, '&nbsp;کله چې زما د حضور جلال هلته تېريږى، نو زۀ به تا د ګټ په يو غټ چاود کښې واچوم او زۀ به تا په خپل لاس سره تر هغې پورې پټ کړم چې تېر شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2422, 'Exodus 33:23', 'Exodus', 33, 23, '&nbsp;بيا به زۀ خپل لاس لرې کړم او تۀ به زما شا ووينې خو زما مخ به نۀ ليدلے کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2423, 'Exodus 34:1', 'Exodus', 34, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل، ”د اولنو په شان دوه د کاڼى تختې جوړې کړه او زۀ به په هغې باندې هم هغه حُکمونه ليکم کوم چې په اولنو تختو باندې وُو، کومې چې تا ماتې کړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2424, 'Exodus 34:2', 'Exodus', 34, 2, '&nbsp;سبا سحر تيار شه او د سينا غرۀ ته راوخېژه او د غرۀ په سر ما ته حاضر شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2425, 'Exodus 34:3', 'Exodus', 34, 3, '&nbsp;هيڅ څوک به تا سره نۀ راخېژى، په ټول غرۀ باندې چې يو کس هم ونۀ ليدلے شى، او نۀ چې د غرۀ په لمن کښې ګډې يا څاروى وڅريږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2426, 'Exodus 34:4', 'Exodus', 34, 4, '&nbsp;نو موسىٰ د اولنو په شان دوه د کاڼو نورې تختې جوړې کړې او سحر وختى هغۀ دا د سينا غرۀ ته د ځان سره وخېژولې، لکه څنګه چې مالِک خُدائ حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2427, 'Exodus 34:5', 'Exodus', 34, 5, '&nbsp;او مالِک خُدائ په وريځ کښې راکوز شو او د هغۀ سره هلته ودرېدلو او خپل مقدس نوم ”مالِک خُدائ“ يې واخستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2428, 'Exodus 34:6', 'Exodus', 34, 6, '&nbsp;مالِک خُدائ د هغۀ په مخکښې تېر شو او دا آواز يې وکړو، ”زۀ، مالِک خُدائ، هغه خُدائ پاک يم چې د رحم او ترس نه ډک يم، په آسانۍ سره نۀ غصه کېږم او ډېره مينه او وفادارى ښايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2429, 'Exodus 34:7', 'Exodus', 34, 7, '&nbsp;زۀ د خپلو خلقو د زرګونو نسلونو سره نۀ بدلېدونکې مينه کوم او زۀ بدى، بغاوت او ګناه هم معاف کوم. خو زۀ مجرم نۀ معاف کوم خو کۀ څوک جرم وکړى نو زۀ به د هغوئ بچو، نمسو درېم او څلورم نسل له هم سزا ورکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2430, 'Exodus 34:8', 'Exodus', 34, 8, '&nbsp;موسىٰ سمدستى خپل سر زمکې ته ټيټ کړو او سجده يې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2431, 'Exodus 34:9', 'Exodus', 34, 9, '&nbsp;هغۀ وفرمائيل، ”اے مالِکه خُدايه، کۀ تۀ په رښتيا زما نه رضا يې زۀ تا ته سوال کوم چې تۀ مونږ سره لاړ شه. زمونږ دا خلق ضديان دى،خو زمونږ بدى او ګناه معاف کړه او مونږ د خپلو خلقو په توګه قبول کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2432, 'Exodus 34:10', 'Exodus', 34, 10, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”اوس زۀ د بنى اِسرائيلو د خلقو سره يو لوظ کوم. زۀ به د دوئ په مخکښې داسې عجيبه عجيبه کارونه وکړم چې په ټوله دُنيا کښې به په يو ځائ کښې او په يو قوم کښې کله هم نۀ وى شوى. ټول خلق به وګورى چې زۀ، مالِک خُدائ څۀ عجيبه کارونه کولے شم،ځکه چې زۀ ستاسو دپاره لوئ لوئ کارونه کوونکے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2433, 'Exodus 34:11', 'Exodus', 34, 11, '&nbsp;نن چې زۀ تاسو له کوم قانون درکوم هغه ومنئ. چې تاسو مخ په وړاندې ځئ نو زۀ به اموريان، کنعانيان، حِويان، فرزيان، حِتيان او يبوسيان ستاسو د مخې نه لرې کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2434, 'Exodus 34:12', 'Exodus', 34, 12, '&nbsp;پام کوئ چې د هغه زمکې د خلقو سره لوظ ونۀ کړئ چې تاسو ور روان يئ، ځکه چې دا به ستاسو دپاره يو دام جوړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2435, 'Exodus 34:13', 'Exodus', 34, 13, '&nbsp;د هغوئ د قربانۍ ځايونه وران کړئ، د هغوئ مقدسې ستنې تباه کړئ او هغوئ له د اشيرې د بُت نښې راوغورزوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2436, 'Exodus 34:14', 'Exodus', 34, 14, '&nbsp;د بل خُدائ عبادت مۀ کوئ، ځکه چې د مالِک خُدائ نوم غېرتى دے، هغه غېرتى خُدائ پاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2437, 'Exodus 34:15', 'Exodus', 34, 15, '&nbsp;د هغه زمکې د خلقو سره چې لوظ ونۀ کړئ، ځکه چې کله هغوئ د خپلو معبودانو عبادت کوى او هغوئ ته قربانۍ پېش کوى، نو تاسو له به هم دعوت درکړى چې د هغوئ سره شريک شئ، او تاسو به په آزمېښت کښې پرېوځئ او خوراک به اوخورئ کوم چې هغوئ خپلو معبودانو ته پېش کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2438, 'Exodus 34:16', 'Exodus', 34, 16, '&nbsp;کېدے شى چې د هغوئ لوڼه تاسو خپلو زامنو ته وادۀ کړئ، نو د هغوئ په وجه به ستاسو زامن نافرمانه شى او د هغوئ به د معبودانو عبادت شروع کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2439, 'Exodus 34:17', 'Exodus', 34, 17, '&nbsp;د ويلې کړے شوو څيزونو نه معبودان مۀ جوړَوئ او مۀ يې عبادت کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2440, 'Exodus 34:18', 'Exodus', 34, 18, '&nbsp;تاسو د پتيرې روټۍ اختر کوئ. لکه څنګه چې ما حُکم درکړے دے، د ابيب په مياشت کښې اووۀ ورځې پتيره روټۍ خورئ، ځکه چې دا هغه مياشت ده چې تاسو په کښې د مِصر نه راووتلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2441, 'Exodus 34:19', 'Exodus', 34, 19, '&nbsp;هر يو مشر زوئ او هر وړومبے پېدا شوے نر څاروے زما دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2442, 'Exodus 34:20', 'Exodus', 34, 20, '&nbsp;خو تاسو به د هر يو وړومبنى پېدا شوى خر په بدل کښې يو ګډُورے پېش کوئ. خو کۀ تاسو دا واپس نۀ اخلئ، نو څټ يې مات کړئ. هر يو وړومبے پېدا شوے زوئ به په بيعه اخلئ. هيڅ څوک به زما په حضور کښې خالى لاسونه نۀ حاضريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2443, 'Exodus 34:21', 'Exodus', 34, 21, '&nbsp;ستاسو سره شپږ ورځې شته چې په هغې کښې خپل کار کولے شئ، خو په اوومه ورځ کار مۀ کوئ، د يوې او د لَو په وخت هم تاسو په اوومه ورځ آرام کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2444, 'Exodus 34:22', 'Exodus', 34, 22, '&nbsp;چې کله تاسو د غنمو وړومبنے فصل رېبل شروع کوئ نو د لَو کولو اختر کوئ او په خزان کښې د فصل راټولولو اختر کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2445, 'Exodus 34:23', 'Exodus', 34, 23, '&nbsp;په کال کښې درې ځل ستاسو ټول نران دې زما مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک عبادت له راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2446, 'Exodus 34:24', 'Exodus', 34, 24, '&nbsp;د هغې نه پس چې کله زۀ قومونه ستاسو د مخې نه لرې کړم او ستاسو علاقه زياته کړم، نو د دې درېو اخترونو په دوران کښې به د هيچا دا طمع پېدا نۀ شى چې ستاسو زمکه ونيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2447, 'Exodus 34:25', 'Exodus', 34, 25, '&nbsp;کله چې تاسو ما ته يو ځناور قربانى کوئ نو خمبيره شوې روټۍ ورسره مۀ پېش کوئ. کوم ځناور چې د فسحې په اختر کښې حلال شوى وى نو د هغې يوه برخه هم د بل سحر پورې مۀ پرېږدئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2448, 'Exodus 34:26', 'Exodus', 34, 26, '&nbsp;هر کال د مالِک خُدائ ستاسو خُدائ پاک کور ته د خپلې زمکې نه رېبلے شوې وړومبۍ غله راوړئ. د چېلۍ بچے د خپلې مور په پيو کښې مۀ پخوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2449, 'Exodus 34:27', 'Exodus', 34, 27, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”دا خبرې وليکه، ځکه چې د دې حُکمونو په بنياد باندې زۀ ستا او د بنى اِسرائيلو سره يو لوظ کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2450, 'Exodus 34:28', 'Exodus', 34, 28, '&nbsp;موسىٰ هلته د مالِک خُدائ سره څلوېښت ورځې او شپې ايسار شو، هغۀ نۀ څۀ خوړل او نۀ يې څۀ څښل. هغۀ په هغه تختو باندې د لوظ خبرې يعنې لس حُکمونه وليکل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2451, 'Exodus 34:29', 'Exodus', 34, 29, '&nbsp;چې کله موسىٰ د لسو حُکمونو د دوو تختو سره د سينا غرۀ نه راکوز شو، نو د هغۀ مخ ځلېدلو ځکه چې هغۀ د مالِک خُدائ سره خبرې کړې وې، خو هغه ترې نه خبر نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2452, 'Exodus 34:30', 'Exodus', 34, 30, '&nbsp;هارون او ټولو خلقو موسىٰ ته وکتل او وې ليدل چې د هغۀ مخ ځلېدلو او هغوئ موسىٰ له نزدې ورتلو نه يرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2453, 'Exodus 34:31', 'Exodus', 34, 31, '&nbsp;خو موسىٰ هغوئ راوغوښتل، نو هارون او د قوم مشران هغۀ له راغلل او موسىٰ د هغوئ سره خبرې وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2454, 'Exodus 34:32', 'Exodus', 34, 32, '&nbsp;د هغې نه پس، ټول بنى اِسرائيل د هغۀ نه راټول شول او موسىٰ هغوئ له هغه ټول حُکمونه ورکړل کوم چې مالِک خُدائ د سينا په غرۀ باندې ورکړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2455, 'Exodus 34:33', 'Exodus', 34, 33, '&nbsp;چې کله موسىٰ د هغوئ سره خبرې ختمې کړې، نو هغۀ په پړده باندې خپل مخ پټ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2456, 'Exodus 34:34', 'Exodus', 34, 34, '&nbsp;چې کله هم موسىٰ د مالِک خُدائ د حضور خېمې ته ننوتلو، نو هغۀ به پړده لرې کوله. او چې هغه به راووتلو، نو بنى اِسرائيلو ته به يې هغه هر څۀ وفرمائيل چې هغۀ له به يې د وئيلو حُکم ورکړے شوے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2457, 'Exodus 34:35', 'Exodus', 34, 35, '&nbsp;او هغوئ به دا ليدل چې د موسىٰ مخ ځليږى. نو هغۀ به په خپل مخ واپس هغه پړده اچوله تر هغه وخته پورې چې بل ځل به هغه د مالِک خُدائ سره خبرو کولو له تلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2458, 'Exodus 35:1', 'Exodus', 35, 1, '&nbsp;بيا موسىٰ د بنى اِسرائيلو ټول قوم راغونډ کړو او هغوئ ته يې وفرمائيل، ”تاسو به د مالِک خُدائ په دې حُکمونو باندې عمل کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2459, 'Exodus 35:2', 'Exodus', 35, 2, '&nbsp;د خپل کار دپاره ستاسو سره شپږ ورځې شته، خو اوومه د سبت مقدسه ورځ يعنې د آرام ورځ ده، هغه ما مالِک خُدائ ته وقف شوې ده. هر څوک چې څۀ قِسم کار هم په هغه ورځ وکړى نو هغه دې ووژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
