(2461, 'Exodus 35:4', 'Exodus', 35, 4, '&nbsp;موسىٰ د بنى اِسرائيلو ټول قوم ته وفرمائيل، ”مالِک خُدائ د دې حُکم کړے دے چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2462, 'Exodus 35:5', 'Exodus', 35, 5, '&nbsp;مالِک خُدائ ته يوه نذرانه پېش کړئ. د چا زړۀ چې غواړى نو داسې څيزونه په نذرانه کښې راوړلے شئ لکه سرۀ زر، سپين زر، يا زېړ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2463, 'Exodus 35:6', 'Exodus', 35, 6, '&nbsp;کتان، د آسمانى رنګ، کاسنى او د سور رنګ وړۍ، د چېلو د وړۍ نه جوړه شوې کپړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2464, 'Exodus 35:7', 'Exodus', 35, 7, '&nbsp;سره رنګ شوې د ګډو څرمن، ښۀ څرمن، د کيکر لرګى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2465, 'Exodus 35:8', 'Exodus', 35, 8, '&nbsp;د ډيوو دپاره تېل، او د غوړولو تېلو دپاره د خوشبويۍ مصالحې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2466, 'Exodus 35:9', 'Exodus', 35, 9, '&nbsp;اونيکس کاڼى او نور قيمتى کاڼى چې د مشر اِمام په پېش بند او د هغۀ د سينې په جېب ولګولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
